<div class="row g-3 mb-4"><div class="col-lg-8"><div class="card border-0 shadow-sm h-100"><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Tipo</dt><dd class="col-sm-8"><?= esc(['ENTRY'=>'Entrada','EXIT'=>'Salida','ADJUSTMENT'=>'Ajuste','REVERSAL'=>'Reversión'][$movement['type']] ?? $movement['type']) ?></dd><dt class="col-sm-4">Registrado por</dt><dd class="col-sm-8"><?= esc($movement['created_by_name']) ?></dd><dt class="col-sm-4">Entrega</dt><dd class="col-sm-8"><?= esc($movement['delivered_by_name']) ?></dd><dt class="col-sm-4">Recibe</dt><dd class="col-sm-8"><?= esc($movement['received_by_name']) ?></dd><?php if ($movement['received_by_area_name']): ?><dt class="col-sm-4">Área receptora</dt><dd class="col-sm-8"><?= esc($movement['received_by_area_name']) ?></dd><?php endif ?><?php if ($movement['supplier_name']): ?><dt class="col-sm-4">Proveedor</dt><dd class="col-sm-8"><?= esc($movement['supplier_name']) ?></dd><?php endif ?><?php if ($movement['document_number']): ?><dt class="col-sm-4">Documento</dt><dd class="col-sm-8"><?= esc($movement['document_number']) ?></dd><?php endif ?><?php if ($movement['reason']): ?><dt class="col-sm-4">Motivo</dt><dd class="col-sm-8"><?= esc($movement['reason']) ?></dd><?php endif ?><?php if ($movement['original_movement_id']): ?><dt class="col-sm-4">Movimiento original</dt><dd class="col-sm-8"><a href="<?= url_to('inventory-movement-show', $movement['original_movement_id']) ?>">Ver #<?= esc((string) $movement['original_movement_id']) ?></a></dd><?php endif ?></dl></div></div></div>
