<?php $dispatchFields = ['guide_number'=>'Guía/remisión','authorization_number'=>'Autorización','issue_date'=>'Fecha de emisión','start_date'=>'Fecha de inicio','end_date'=>'Fecha de fin','issuer_name'=>'Emisor','issuer_tax_identifier'=>'RUC/C.I. emisor','transporter_name'=>'Transportista','transporter_identifier'=>'RUC/C.I. transportista','vehicle_plate'=>'Placa','origin_place'=>'Partida','destination_name'=>'Destinatario','destination_identifier'=>'RUC/C.I. destinatario','destination_address'=>'Dirección de destino','route_description'=>'Ruta','related_document_number'=>'Documento relacionado','description'=>'Descripción']; ?>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5 mb-3">Guía o remisión</h2><?php if ($sourceDispatch !== null): ?><div class="alert alert-info">Esta es una entrega posterior de <a href="<?= url_to('inventory-movement-show', $sourceDispatch['movement_id']) ?>"><?= esc($sourceDispatch['guide_number'] ?: $sourceDispatch['movement_number']) ?></a>.</div><?php endif ?><dl class="row mb-4"><?php foreach ($dispatchFields as $field => $label): ?><?php if ($dispatch[$field] !== null && $dispatch[$field] !== ''): ?><dt class="col-md-3"><?= esc($label) ?></dt><dd class="col-md-9"><?= esc($dispatch[$field]) ?></dd><?php endif ?><?php endforeach ?></dl>
<div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Producto</th><th class="text-end">Solicitado</th><th class="text-end">Entregado acumulado</th><th class="text-end">Pendiente vigente</th><th>Estado</th></tr></thead><tbody><?php foreach ($dispatchItems as $line): ?><?php $delivered = (float) $line['effective_delivered_quantity']; $pending = (float) $line['effective_pending_quantity']; $effectiveStatus = $pending <= 0 ? 'DELIVERED' : ($delivered > 0 ? 'PARTIAL' : 'PENDING'); ?><tr><td><span class="font-monospace"><?= esc($line['material_code']) ?></span> · <?= esc($line['material_name']) ?></td><td class="text-end"><?= esc(number_format((float) $line['requested_quantity'], 3, ',', '.')) ?> <?= esc($line['unit_symbol']) ?></td><td class="text-end"><?= esc(number_format($delivered, 3, ',', '.')) ?> <?= esc($line['unit_symbol']) ?></td><td class="text-end"><?= esc(number_format($pending, 3, ',', '.')) ?> <?= esc($line['unit_symbol']) ?></td><td><span class="badge text-bg-<?= $effectiveStatus === 'DELIVERED' ? 'success' : ($effectiveStatus === 'PARTIAL' ? 'warning' : 'danger') ?>"><?= esc(['DELIVERED'=>'Entregado','PARTIAL'=>'Parcial','PENDING'=>'Pendiente'][$effectiveStatus]) ?></span></td></tr><?php endforeach ?></tbody></table></div><?php if ($followupDispatches !== []): ?><hr><h3 class="h6">Entregas posteriores</h3><ul class="mb-0"><?php foreach ($followupDispatches as $followup): ?><li><a href="<?= url_to('inventory-movement-show', $followup['movement_id']) ?>"><?= esc($followup['guide_number'] ?: $followup['movement_number']) ?></a> · <?= esc($followup['issue_date'] ?? 'Sin fecha') ?></li><?php endforeach ?></ul><?php endif ?></div></div>
<?php endif ?>
<div class="card border-0 shadow-sm mb-4"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Material</th><th class="text-end">Cantidad</th><th class="text-end">Stock anterior</th><th class="text-end">Stock posterior</th><?php if ($showCosts): ?><th class="text-end">Costo unitario original</th><th class="text-end">Valor original</th><?php endif ?><th>Valoración</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><span class="font-monospace"><?= esc($item['material_code']) ?></span> · <?= esc($item['material_name']) ?></td><td class="text-end"><?= $item['direction'] > 0 ? '+' : '-' ?><?= esc(number_format((float) $item['quantity'], 3, ',', '.')) ?> <?= esc($item['unit_symbol']) ?></td><td class="text-end"><?= esc(number_format((float) $item['stock_before'], 3, ',', '.')) ?></td><td class="text-end"><?= esc(number_format((float) $item['stock_after'], 3, ',', '.')) ?></td><?php if ($showCosts): ?><td class="text-end"><?= $item['unit_cost'] === null ? '—' : esc(number_format((float) $item['unit_cost'], 6, ',', '.')) ?></td><td class="text-end"><?= esc(number_format((float) $item['line_value'], 2, ',', '.')) ?></td><?php endif ?><td><?= (float) $item['remaining_valuation'] > 0 ? '<span class="badge text-bg-warning">Pendiente</span>' : '<span class="badge text-bg-success">Completa</span>' ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 mb-1">Archivos de respaldo</h2><p class="text-body-secondary mb-0">PDF o imagen privada, máximo 10 MB.</p></div></div>
<?php if (auth()->user()?->can('files.upload')): ?><form class="row g-2 align-items-end mb-4" method="post" enctype="multipart/form-data" action="<?= url_to('inventory-attachment-upload', $movement['id']) ?>"><?= csrf_field() ?><div class="col-md-9"><label class="form-label" for="attachment">Seleccionar archivo</label><input class="form-control" type="file" id="attachment" name="attachment" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required></div><div class="col-md-3"><button class="btn btn-primary w-100" type="submit">Cargar respaldo</button></div></form><?php endif ?>
<div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Archivo</th><th>Tipo</th><th>Tamaño</th><th>Subido por</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach ($attachments as $attachment): ?><tr><td><?= esc($attachment['original_name']) ?><div class="small text-body-secondary font-monospace">SHA-256: <?= esc(substr($attachment['sha256'], 0, 16)) ?>…</div></td><td><?= esc($attachment['mime_type']) ?></td><td><?= esc(number_format((float) $attachment['size_bytes'] / 1024, 1, ',', '.')) ?> KB</td><td><?= esc($attachment['uploaded_by_name']) ?><div class="small text-body-secondary"><?= esc($attachment['uploaded_at']) ?></div></td><td><span class="badge text-bg-<?= $attachment['status'] === 'ACTIVE' ? 'success' : 'secondary' ?>"><?= $attachment['status'] === 'ACTIVE' ? 'Activo' : 'Archivado' ?></span></td><td><div class="d-flex flex-wrap gap-2"><?php if ($attachment['status'] === 'ACTIVE' && auth()->user()?->can('files.download')): ?><a class="btn btn-sm btn-outline-primary" href="<?= url_to('inventory-attachment-download', $attachment['id']) ?>">Descargar</a><?php endif ?><?php if ($attachment['status'] === 'ACTIVE' && auth()->user()?->can('files.archive')): ?><form method="post" action="<?= url_to('inventory-attachment-archive', $attachment['id']) ?>" class="d-flex gap-2"><?= csrf_field() ?><input class="form-control form-control-sm" name="reason" minlength="5" maxlength="1000" placeholder="Motivo" required><button class="btn btn-sm btn-outline-warning" type="submit">Archivar</button></form><?php endif ?></div></td></tr><?php endforeach ?><?php if ($attachments === []): ?><tr><td colspan="6" class="text-center text-body-secondary py-4">No hay archivos adjuntos.</td></tr><?php endif ?></tbody></table></div></div></div>
<?php if ($movement['type'] !== 'REVERSAL' && (int) $movement['is_reversed'] === 0 && auth()->user()?->can('inventory.reversals.request')): ?><div class="card border-warning"><div class="card-body"><h2 class="h5">Solicitar reversión</h2><p class="text-body-secondary">El movimiento original no cambiará. Otro administrador deberá aprobar el movimiento compensatorio.</p><form method="post" action="<?= url_to('inventory-reversal-request', $movement['id']) ?>"><?= csrf_field() ?><div class="input-group"><input class="form-control" name="reason" minlength="5" maxlength="2000" placeholder="Motivo obligatorio" required><button class="btn btn-outline-warning" type="submit">Solicitar</button></div></form></div></div><?php endif ?>
